<?php
/**
 * @var SeoControlCenter\Core\View\Template $view
 * @var SeoControlCenter\Domain\Projects\Project $project
 * @var list<SeoControlCenter\Domain\Opportunities\OpportunityOutcome> $outcomes
 * @var bool $canEdit
 */
$view->extend('layouts/app', ['title' => 'Predicted vs observed · ' . $project->name]);
$base = '/projects/' . $project->publicId;
?>
<?= $view->partial('partials/project-header', ['project' => $project, 'active' => 'opportunities']) ?>
<h2>Predicted vs observed</h2><p><a href="<?= $view->e($base . '/opportunities') ?>">All findings</a></p>
<p class="muted">Correlation, not attribution. Google Search Console calendar days use Pacific time. Completion day is excluded. Baseline: preceding 28 days; day 28: following days 1–28; day 56: days 29–56. Missing daily imports or an unobserved subject stay pending. Click changes are normalized to 30 days. Shows the latest 50 checkpoints.</p>
<p class="muted">Done? An outcome is <strong>verified</strong> when page monitoring saw the page change within 14 days of completion, or <strong>confirmed</strong> when someone says so. Results marked <strong>not done</strong> leave the estimate calibration. Both checkpoints of a completion share this state; change it on the day-28 row. <strong>Overlaps</strong> are other changes in the same window, so the result may not be this change alone; the calibration prefers results without overlaps once there are five.</p>
<table><thead><tr><th>Subject / completion</th><th>Checkpoint</th><th>Predicted monthly gain</th><th>Baseline clicks / position / CTR</th><th>Observed clicks / position / CTR</th><th>Observed monthly change</th><th>Done?</th><th>Overlaps</th><th>Context</th></tr></thead><tbody>
<?php foreach ($outcomes as $row): ?><tr><td><?= $view->e($row->subject) ?><br><?= $view->e($row->completedOn) ?></td><td><?= $view->e($row->checkpoint) ?> days</td><td><?= $row->predictedClicks !== null ? $view->e(number_format($row->predictedClicks, 1)) : 'unknown' ?></td><td><?= $row->baseline !== null ? $view->e($row->baseline->clicks . ' / ' . ($row->baseline->position ?? 'unknown') . ' / ' . ($row->baseline->ctr() !== null ? number_format(100 * $row->baseline->ctr(), 2) . '%' : 'unknown')) : 'pending / unknown' ?></td><td><?= $row->actual !== null ? $view->e($row->actual->clicks . ' / ' . ($row->actual->position ?? 'unknown') . ' / ' . ($row->actual->ctr() !== null ? number_format(100 * $row->actual->ctr(), 2) . '%' : 'unknown')) : 'pending / unknown' ?></td><td><?= $row->monthlyChange() !== null ? $view->e(number_format($row->monthlyChange(), 1)) : 'pending / unknown' ?></td><td><?= $view->e(match ($row->implementation) { 'verified' => 'Verified: page changed', 'confirmed' => 'Confirmed', 'not_implemented' => 'Not done', default => 'Not verified' }) ?><?php if ($canEdit && $row->checkpoint === 28): ?><form method="post" action="<?= $view->e($base . '/opportunities/outcomes/' . $row->publicId . '/implementation') ?>" class="inline-form"><?= $view->csrfField() ?><?php if ($row->implementation !== 'confirmed'): ?><button type="submit" name="implemented" value="1" class="button button-small button-ghost">Confirm done</button><?php endif; ?><?php if ($row->implementation !== 'not_implemented'): ?> <button type="submit" name="implemented" value="0" class="button button-small button-ghost">Not done</button><?php endif; ?></form><?php endif; ?></td><td><?php if ($row->overlaps === []): ?><?= $row->measuredAt !== null ? 'None found' : 'Checked when measured' ?><?php else: ?><ul><?php foreach ($row->overlaps as $overlap): ?><li><?= $view->e($overlap['date'] . ' · ' . $overlap['label']) ?></li><?php endforeach; ?></ul><?php endif; ?></td><td><a href="<?= $view->e($base . '/opportunities/' . $row->opportunityId . '/task') ?>">Task</a><?php if ($row->annotationId !== null): ?> · <a href="<?= $view->e($base . '/annotations/' . $row->annotationId . '/impact') ?>">Annotation impact</a><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table>
<?php if ($outcomes === []): ?><p>Mark an opportunity or task done to capture a baseline.</p><?php endif; ?>
